const trig = $('Execute Workflow Trigger').first().json;
// Tasks, weekly items and projects come from the shared "Read Plan Tree" (the Projects Coach reads the same tree)
let tree = {};
try { tree = $('Read Plan Tree').first().json || {}; } catch (e) { tree = {}; }
const treeFailed = !Array.isArray(tree.tasks);
const open = (tree.tasks || []).filter((t) => t.status !== 'Done' && t.status !== 'Cancelled').sort((a, b) => String(a.due || '9999').localeCompare(String(b.due || '9999')));
const tl = open.map((t) => `- ${t.id} | ${t.name} | ${t.priority ?? '-'} | due ${t.due ?? '-'} | ${t.timing ?? '-'} | ${t.status ?? '-'} | ${t.complexity ?? 'no complexity'} | moved ${t.moved ?? 0} | weekly item ${t.weekly_item ?? '-'} | subtasks ${t.subtasks ?? 0}`);
const events = $('Fetch Calendar Events For Snapshot').all().map((i) => i.json).filter((e) => e && e.id);
const el = events.map((e) => `- ${e.id} | ${e.summary || '(no title)'} | ${(e.start && (e.start.dateTime || e.start.date)) || '-'} to ${(e.end && (e.end.dateTime || e.end.date)) || '-'}`);
// Long-term memory from Notion, read on every message (the agent's own page and the shared page): what he asked to remember
const memText = (n) => { try { const j = $(n).first().json; return typeof j.markdown === 'string' ? j.markdown.split('\n').filter((l) => !l.startsWith('>')).join('\n').trim() : null; } catch (e) { return null; } };
const ownMem = memText('Fetch Agent Memory'), sharedMem = memText('Fetch Shared Memory');
const memFailed = [ownMem === null ? 'your memory page' : '', sharedMem === null ? 'the shared memory page' : ''].filter(Boolean);
const memory = 'WHAT YOU KNOW ABOUT ALEX (your Notion memory, read just now: apply every line)\n' + (memFailed.length ? 'MEMORY READ FAILED for ' + memFailed.join(' and ') + ': call Recall Memory once.\n' : '') + '# Shared page (all agents)\n' + (sharedMem || '-') + '\n# Your page\n' + (ownMem || '-');
// A read that failed returns an error item instead of rows: say so, so an empty list is not read as "nothing open"
const failedReads = ['Fetch Calendar Events For Snapshot'].filter((n) => { try { return $(n).all().some((i) => i.json && i.json.error); } catch (e) { return true; } });
if (treeFailed) failedReads.push('Read Plan Tree');
for (const n of (tree.read_failed || [])) failedReads.push(n);
// A MEMORY UPDATE note from "Read Plan Tree" (a rename or status change found by Notion page id) goes right after memory, so the agent sees it this turn; Prepare Memory Writes keeps it in the chat memory for later turns
const memNote = (() => { try { return String($('Read Plan Tree').first().json.memory_note || ''); } catch (e) { return ''; } })();
const snapshot = memory + '\n\n' + (memNote ? memNote + '\n\n' : '') + (failedReads.length ? 'NOTION READ FAILED: ' + failedReads.join(', ') + '. These lists may be incomplete.\n\n' : '') + `OPEN DAILY TASKS (${tl.length}):\n${tl.join('\n') || '(none)'}\n\n${tree.text || 'PLAN TREE: not available (Read Plan Tree failed).'}\n\nCALENDAR EVENTS, next 7 days (${el.length}):\n${el.join('\n') || '(none)'}`;
// A report (the 7am plan, the 7pm wrap-up, "what today / tomorrow / this week", "plan my day") is built from Notion only: the agent gets no chat history for it
const report = /^It's (7am|7pm)|\bplan (my|the) day\b|today'?s plan|\bwhat('?s| is| do i have)?( on| left)?( for| from)? (today|tomorrow|this week|next week)\b/i.test(String(trig.chatInput || ''));
return [{ json: { chat_id: trig.chat_id, chatInput: trig.chatInput, agent_name: trig.agent_name, snapshot, report } }];

// Notion writes this turn REALLY made, read from the agent's own tool calls and Notion's answers (never from the reply text).
// A write whose answer carries no saved id is left out: nothing was saved.
// Each line names the row (title from this run's reads or from the write itself) and the fields written, so memory alone shows what changed.
const SOURCES = ["Read Plan Tree", "Fetch Calendar Events For Snapshot"];
const out = $input.first().json;
const trig = $('Execute Workflow Trigger').first().json;
const WRITE = /create|update|add|confirm|mark|delete|trash|archive|log weekly/i;
const ID = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g;
const TITLE_KEYS = ['Task Name', 'Subtask Name', 'Description', 'Name', 'Review', 'Title'];
const names = {};
const titleOf = (o) => {
  if (typeof o.name === 'string' && o.name) return o.name;
  if (typeof o.summary === 'string' && o.summary) return o.summary;
  for (const [k, v] of Object.entries(o.properties || {})) {
    if (v && v.type === 'title') return (v.title || []).map(t => t.plain_text).join('');
    if (TITLE_KEYS.includes(k) && typeof v === 'string') return v;
  }
  return null;
};
const collect = (x, depth = 0) => {
  if (depth > 8) return;
  if (typeof x === 'string') { if (!/^\s*[\[{]/.test(x)) return; try { x = JSON.parse(x); } catch (e) { return; } }
  if (Array.isArray(x)) { x.forEach(v => collect(v, depth + 1)); return; }
  if (!x || typeof x !== 'object') return;
  if (typeof x.id === 'string' && !names[x.id]) { const t = titleOf(x); if (t) names[x.id] = t; }
  for (const v of Object.values(x)) if (v && (typeof v === 'object' || typeof v === 'string')) collect(v, depth + 1);
};
for (const n of SOURCES) { try { collect($(n).all().map(i => i.json)); } catch (e) { /* that read did not run */ } }
const steps = out.intermediateSteps || [];
for (const s of steps) collect(s.observation);
const short = (v) => (typeof v === 'string' ? v : JSON.stringify(v)).replace(/\s+/g, ' ').slice(0, 150);
const lines = [];
for (const step of steps) {
  const tool = String((step.action && step.action.tool) || '');
  if (!WRITE.test(tool)) continue;
  const obs = typeof step.observation === 'string' ? step.observation : JSON.stringify(step.observation ?? '');
  // An error answer saved nothing, even though it carries ids (request_id, integration_id, the data_source id)
  if (/APIResponseError|"error"\s*:|object_not_found|validation_error|Could not find|MCP error|timed out/i.test(obs)) continue;
  const ids = [...new Set(obs.match(ID) || [])];
  if (!ids.length || /"properties":\{\}/.test(obs)) continue;
  const inp = (step.action && step.action.toolInput) ?? {};
  const label = (id) => (names[id] ? '"' + names[id] + '" (' + id + ')' : id);
  // ids already in the input are the row being updated or rows the new one links to; the others are the rows just created
  const inInput = JSON.stringify(inp);
  const isCreate = /create|add/i.test(tool);
  const saved = isCreate ? ids.filter(id => !inInput.includes(id)) : ids;
  const linked = isCreate ? ids.filter(id => inInput.includes(id)) : [];
  const fields = (p) => Object.entries(p).map(([k, v]) => k + ' = ' + short(v)).join('; ');
  const props = inp && typeof inp === 'object' && inp.properties && typeof inp.properties === 'object' && !Array.isArray(inp.properties) ? inp.properties : null;
  const pages = inp && typeof inp === 'object' && Array.isArray(inp.pages) ? inp.pages : null;
  const written = props ? fields(props) : pages ? pages.map(p => fields(p.properties || {})).join(' || ') : JSON.stringify(inp).replace(/\s+/g, ' ').slice(0, 700);
  lines.push('- ' + tool + ' -> saved in Notion: ' + (saved.length ? saved : ids).map(label).join(', ') + (linked.length ? ' | linked to: ' + linked.map(label).join(', ') : '') + ' | written: ' + written);
}
const action_log = lines.length
  ? '[ACTION LOG, ' + $now.toFormat('yyyy-LL-dd HH:mm') + ', written by the workflow from the tool results of my previous reply: these Notion writes are DONE. Never make them again.]\n' + lines.join('\n')
  : '';
const { intermediateSteps, ...reply } = out;
// The agent sometimes copies an earlier action log from its chat memory into its reply: never send it
if (typeof reply.output === 'string') reply.output = reply.output.replace(/\s*\[ACTION LOG[^\]\n]*\][^\n]*(\n- [^\n]*)*/g, '').trim();
return [{ json: { ...reply, chat_id: String(trig.chat_id ?? ''), agent_name: trig.agent_name || 'productivity', action_log } }];

// The tasks card for Telegram, read from Notion AFTER this turn's writes. It is the only list he sees: the agent never lists tasks.
// Which days: the agent's last line "[card: <date>]" or "[card: <date> to <date>]"; else, after a write, every day the write touched;
// else the check-in or question (today, tomorrow, the week). "[card: none]" with no write = no card.
// One day: a day heading, then weekly goal -> task -> subtasks. Several days: one heading for the range, the day before each task.
// Every goal of the range, every task and every subtask, full names; Cancelled rows are left out; open tasks from earlier days come last.
const trig = $('Execute Workflow Trigger').first().json;
const act = $('Build Action Log').first().json;
const log = String(act.action_log || '');
const reply = String(act.output || '');
const rows = (n) => { try { return $(n).all().map((i) => i.json).filter((r) => r && r.id); } catch (e) { return []; } };
const goals = rows('Fetch Week Goals For Progress');
const tasks = rows('Fetch Week Tasks For Progress');
const subs = rows('Fetch Week Subtasks For Progress');
const taskById = Object.fromEntries(tasks.map((t) => [t.id, t]));
const subById = Object.fromEntries(subs.map((s) => [s.id, s]));
const goalById = Object.fromEntries(goals.map((g) => [g.id, g]));
// Full title: Notion splits a title at a link (e.g. "CLAUDE.md"), so "name" may hold only its first piece
const title = (r) => String(r.property_task_name || r.property_subtask_name || r.name || '').trim();
const status = (r) => r.property_status || '';
const live = (r) => status(r) !== 'Cancelled';
const open = (r) => !['Done', 'Cancelled'].includes(status(r));
const due = (r) => ((r.property_due_date || {}).start || '').slice(0, 10);
const byDue = (a, b) => (due(a) < due(b) ? -1 : due(a) > due(b) ? 1 : 0);
const D = (iso) => DateTime.fromISO(iso, { zone: 'Europe/Rome' }).setLocale('en');
const count = (ids, byId) => {
  let done = 0, total = 0;
  for (const id of ids || []) {
    const r = byId[id];
    if (!r || !live(r)) continue;
    total++;
    if (status(r) === 'Done') done++;
  }
  return { done, total };
};
const subList = (t) => (t.property_subtasks || []).map((id) => subById[id]).filter((s) => s && live(s)).map((s) => ({ name: title(s), status: status(s) }));
const taskView = (t, dayLabel) => { const c = count(t.property_subtasks, subById); return { name: title(t), status: status(t), done: c.done, total: c.total, day: dayLabel, due: due(t), subtasks: subList(t) }; };
const isGoal = (g) => (g.property_type || 'Goal') === 'Goal' && live(g);
const goalOf = (t) => (t.property_weekly_item || []).map((id) => goalById[id]).find((g) => g && isGoal(g));
const firstDue = (g) => (g.tasks.length ? g.tasks[0].due : '9999');
const byFirst = (a, b) => (firstDue(a) < firstDue(b) ? -1 : firstDue(a) > firstDue(b) ? 1 : 0);

// The days to show
const today = $now.setZone('Europe/Rome').toISODate();
const weekend = $now.setZone('Europe/Rome').weekday >= 6;
// When he plans or asks for "the week" on Saturday or Sunday, he means the coming week
const planMon = (weekend ? $now.plus({ weeks: 1 }) : $now).setZone('Europe/Rome').startOf('week');
const card = [...reply.matchAll(/\[card:\s*([^\]\n]*)\]/gi)].pop();
const want = card ? card[1].trim().toLowerCase() : '';
const dates = want.match(/\d{4}-\d{2}-\d{2}/g) || [];
const touched = new Set(log.match(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g) || []);
const touchedDays = new Set();
for (const id of touched) {
  if (taskById[id] && live(taskById[id]) && due(taskById[id])) touchedDays.add(due(taskById[id]));
  if (subById[id]) for (const tid of subById[id].property_task || []) if (taskById[tid] && due(taskById[tid])) touchedDays.add(due(taskById[tid]));
}
// A goal written with no task of it touched: show its week
const touchedGoals = goals.filter((g) => touched.has(g.id) && isGoal(g) && due(g));
const text = String(trig.chatInput || '');
let mode = 'none', from = '', to = '';
if (dates.length) { mode = 'range'; from = dates[0]; to = dates[dates.length - 1]; if (to < from) [from, to] = [to, from]; }
else if (touchedDays.size) mode = 'days';
else if (touchedGoals.length) { mode = 'range'; const s = D(due(touchedGoals[0])); from = s.startOf('week').toISODate(); to = s.endOf('week').toISODate(); }
else if (want !== 'none') {
  if (/^It's 7am/i.test(text)) { mode = 'range'; from = to = today; }
  else if (/^It's 7pm/i.test(text)) { mode = 'range'; from = today; to = $now.plus({ days: 1 }).toISODate(); }
  else if (/^It's Saturday|AUTOMATIC WEEKLY REVIEW/i.test(text)) mode = 'none';
  else if (/\btomorrow\b/i.test(text)) { mode = 'range'; from = to = $now.plus({ days: 1 }).toISODate(); }
  else if (/\bnext week\b/i.test(text)) { mode = 'range'; const m = $now.startOf('week').plus({ weeks: 1 }); from = m.toISODate(); to = m.endOf('week').toISODate(); }
  else if (/\bweek\b/i.test(text)) { mode = 'range'; from = planMon.toISODate(); to = planMon.endOf('week').toISODate(); }
  else if (/\btoday\b/i.test(text)) { mode = 'range'; from = to = today; }
}

// One block of days: goals of those days (in a week range also the week's goals with no task yet), then "Other tasks"
const block = (a, b, showDay) => {
  const list = tasks.filter((t) => live(t) && due(t) >= a && due(t) <= b).sort(byDue);
  const label = (t) => (showDay ? D(due(t)).toFormat('ccc d') : '');
  const byGoal = new Map();
  const loose = [];
  for (const t of list) { const g = goalOf(t); if (g) { if (!byGoal.has(g.id)) byGoal.set(g.id, []); byGoal.get(g.id).push(t); } else loose.push(t); }
  const weekGoals = showDay ? goals.filter((g) => isGoal(g) && due(g) >= a && due(g) <= D(b).endOf('week').toISODate() && due(g) >= D(a).startOf('week').toISODate()) : [];
  for (const g of weekGoals) if (!byGoal.has(g.id)) byGoal.set(g.id, []);
  const out = [...byGoal.entries()].map(([id, ts]) => {
    const g = goalById[id];
    const c = count(g.property_daily_tasks, taskById);
    return { name: title(g), done: c.done, total: c.total, tasks: ts.map((t) => taskView(t, label(t))), empty: 'no tasks planned yet' };
  });
  out.sort(byFirst);
  if (loose.length) out.push({ name: 'Other tasks', kind: 'other', done: 0, total: 0, tasks: loose.map((t) => taskView(t, label(t))) });
  return out;
};
const dayHeading = (iso) => D(iso).toFormat('cccc d LLL');
const sections = [];
if (mode === 'days') {
  for (const d of [...touchedDays].sort()) sections.push({ heading: dayHeading(d), goals: block(d, d, false) });
} else if (mode === 'range') {
  sections.push({ heading: from === to ? dayHeading(from) : D(from).toFormat('ccc d LLL') + ' – ' + D(to).toFormat('ccc d LLL'), goals: block(from, to, from !== to) });
  // Open tasks from days before the range (and before today), with their date
  const before = from < today ? from : today;
  const late = tasks.filter((t) => open(t) && due(t) && due(t) < before).sort(byDue);
  if (late.length) sections.push({ heading: 'Still open from earlier days', kind: 'overdue', goals: [{ name: 'Not done yet', kind: 'other', done: 0, total: 0, tasks: late.map((t) => taskView(t, D(due(t)).toFormat('ccc d LLL'))) }] });
}
const shown = sections.filter((s) => s.goals.length);
return [{ json: { progress: shown.length ? { sections: shown } : {} } }];

// What this turn adds to the agent's chat memory (Postgres), saved in one go by Save To Memory, in this order:
// 1. the MEMORY UPDATE note from "Read Plan Tree" (a project or goal renamed, or a project's status changed, matched by Notion page id);
//    the agent already saw it in its snapshot this turn, the memory keeps it for later turns;
// 2. a report (7am, 7pm, "what today / tomorrow / this week", "plan my day") ran with NO chat history:
//    its question and answer are added to the chat, so a later reply is understood;
// 3. the ACTION LOG: the Notion writes this turn really made (from Build Action Log).
// Messages are stored exactly as the Chat Memory Manager stored them (notes and logs hidden).
const snap = $('Build Live Snapshot').first().json;
const session_id = 'demo-' + snap.chat_id + '-' + snap.agent_name;
const note = String($('Read Plan Tree').first().json.memory_note || '');
const log = String($('Build Action Log').first().json.action_log || '');
const human = (content) => ({ type: 'human', content, additional_kwargs: {}, response_metadata: {} });
const ai = (content, hidden) => ({ type: 'ai', content, tool_calls: [], additional_kwargs: hidden ? { hideFromUI: true } : {}, response_metadata: {}, invalid_tool_calls: [] });
const writes = [];
const add = (message) => writes.push({ op: 'add', session_id, message });
if (note) add(ai(note, true));
if (snap.report === true) {
  add(human(String(snap.chatInput || '')));
  add(ai(String($('Productivity Agent').first().json.output || '')));
}
if (log) add(ai(log, true));
return [{ json: { writes } }];
